import React, { useState } from 'react';
import axios from 'axios';
import { Home, X } from 'lucide-react';

const CreateGig = () => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [images, setImages] = useState([]);
  const [price, setPrice] = useState('');
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const formData = new FormData();
      formData.append('title', title);
      formData.append('description', description);
      images.forEach((image, index) => {
        formData.append(`images[${index}]`, image);
      });
      formData.append('price', price);

      await axios.post('/api/gigs', formData, {
        headers: {
          'Content-Type': 'multipart/form-data'
        }
      });
      window.location.href = '/dashboard';
    } catch (err) {
      setError(err.response ? err.response.data.message : 'An error occurred.');
    }
  };

  const handleCancel = () => {
    window.location.href = '/dashboard';
  };

  return (
    <div className='flex justify-center items-center h-screen bg-gray-100'>
      <div className='bg-white/10 backdrop-blur-md border border-white/20 shadow-xl p-8 rounded-lg w-full max-w-md'>
        <h2 className='text-2xl font-bold mb-6 text-center'>Create Gig</h2>
        {error && <p className='text-red-500 mb-4'>{error}</p>}
        <form onSubmit={handleSubmit} encType='multipart/form-data'>
          <div className='mb-4'>
            <label htmlFor='title' className='block text-sm font-medium text-gray-700'>Title</label>
            <input
              type='text'
              id='title'
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
              className='mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm'
            />
          </div>
          <div className='mb-4'>
            <label htmlFor='description' className='block text-sm font-medium text-gray-700'>Description</label>
            <textarea
              id='description'
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className='mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm'
            />
          </div>
          <div className='mb-4'>
            <label htmlFor='images' className='block text-sm font-medium text-gray-700'>Images</label>
            <input
              type='file'
              id='images'
              multiple
              onChange={(e) => setImages(e.target.files)}
              className='mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm'
            />
          </div>
          <div className='mb-4'>
            <label htmlFor='price' className='block text-sm font-medium text-gray-700'>Price</label>
            <input
              type='number'
              id='price'
              value={price}
              onChange={(e) => setPrice(e.target.value)}
              required
              className='mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm'
            />
          </div>
          <div className='flex justify-between'>
            <button type='submit' className='bg-indigo-600 text-white py-2 px-4 rounded hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500'>Create Gig</button>
            <button type='button' onClick={handleCancel} className='bg-gray-300 text-gray-700 py-2 px-4 rounded hover:bg-gray-400 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500'>Cancel</button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CreateGig;
